import{_ as r,a,b as i,c as n,d as s,e as l,f as c,g as d,h as p,i as u,j as h,k as m,l as g,m as b,n as f,o as y,p as k,q as w,r as x,s as _,t as v,u as S}from"./chunks/pic22.C2Xo-waF.js";import{_ as C,o as P,c as A,ad as o,j as e,a as I}from"./chunks/framework.BJi0JF_z.js";const T="/Diana-Cl/zizifn/pic8.png",H=JSON.parse('{"title":"ZiZifn Worker Setup Guide","description":"Step-by-step tutorial on forking the repository, retrieving Cloudflare credentials, deploying automatically with GitHub Actions, and generating VLESS proxy configurations.","frontmatter":{"layout":"doc","outline":"deep","lang":"en-US","dir":"ltr","title":"ZiZifn Worker Setup Guide","description":"Step-by-step tutorial on forking the repository, retrieving Cloudflare credentials, deploying automatically with GitHub Actions, and generating VLESS proxy configurations.","date":"2026-10-07T00:00:00.000Z","category":"Tools & Servers","icon":"⚙️","editLink":true,"head":[["meta",{"name":"description","content":"Complete tutorial for deploying a WebAssembly & Rust-based VLESS proxy on Cloudflare Workers using GitHub Actions."}],["meta",{"name":"keywords","content":"Serverless Runtime, cloudflare worker, vless proxy, github actions, rust wasm, zizifn, wrangler deploy"}]]},"headers":[],"relativePath":"en/topics/zizifn.md","filePath":"en/topics/zizifn.md"}'),G={name:"en/topics/zizifn.md"};function q(R,t,N,U,D,E){return P(),A("div",null,[...t[0]||(t[0]=[o('<h1 id="comprehensive-deployment-setup-guide" tabindex="-1">Comprehensive Deployment &amp; Setup Guide <a class="header-anchor" href="#comprehensive-deployment-setup-guide" aria-label="Permalink to &quot;Comprehensive Deployment &amp; Setup Guide&quot;">​</a></h1><p id="serverless-runtime"><strong>Step-by-step guide to forking, configuring security secrets, running GitHub Actions, and obtaining VLESS subscription links</strong></p><br><p align="center"><img src="'+a+'" alt="Zizifn-Main-Page"></p><br><p>The <strong>zizifn</strong> project is a secure proxy configuration based on the VLESS-WS-TLS/TCP protocol. Specific core components are developed in Rust and compiled to WebAssembly (Wasm), running seamlessly on Cloudflare Workers using Wrangler. To deploy this project on your personal Cloudflare account, follow the step-by-step instructions below.</p><blockquote><p><strong>Cloudflare Errors 1101 and 1102</strong></p><p>In this new architecture, there is no need for junk code inside JavaScript, heavy obfuscation, or function renaming!<br> The critical section that triggered these errors has been completely rewritten in Rust, compiled into Wasm, and deployed efficiently.</p></blockquote><br><h2>📚 Table of Contents</h2><nav class="table-of-contents"><ul><li><a href="#fork">Step 1: Forking the Repository</a></li><li><a href="#token">Step 2: Retrieving API Token from Cloudflare</a><ul><li><a href="#api">Creating a Token with Worker Edit Permissions</a></li></ul></li><li><a href="#env">Step 3: Configuring GitHub Secrets</a></li><li><a href="#manual-deploy">Step 4: Enabling and Running GitHub Actions</a></li><li><a href="#how-to-use">How to Use</a><ul><li><a href="#accessing-the-management-panel">Accessing the Management Panel</a></li><li><a href="#sub">Retrieving Subscription Links</a></li></ul></li><li><a href="#pattng">Additional Details</a></li></ul></nav><br><h2 id="fork" tabindex="-1">Step 1: Forking the Repository <a class="header-anchor" href="#fork" aria-label="Permalink to &quot;Step 1: Forking the Repository {#fork}&quot;">​</a></h2><p>First, you need to create a copy of this repository on your GitHub account.</p><ol><li><p>Go to the project&#39;s main repository page <a href="https://github.com/NiREvil/zizifn" target="_blank" rel="noreferrer">(Link)</a>.</p></li><li><p>Click on the <strong>Fork</strong> button at the top right of the page (marked with a red arrow).</p></li></ol><details class="details custom-block"><summary>View Screenshot</summary><p align="center"><img src="'+i+'" alt="How to fork the repository on GitHub" width="1080px"></p></details><br><ol start="3"><li>On the next page, you can optionally rename your fork; otherwise, leave the default name and click <strong>Create fork</strong> to transfer the project to your account.</li></ol><details class="details custom-block"><summary>View Screenshot</summary><p align="center"><img src="'+n+'" alt="How to fork the repository on GitHub" width="1080px"></p></details><br><h2 id="token" tabindex="-1">Step 2: Retrieving API Token from Cloudflare <a class="header-anchor" href="#token" aria-label="Permalink to &quot;Step 2: Retrieving API Token from Cloudflare {#token}&quot;">​</a></h2><p>For automated deployment, GitHub Actions requires access to your Cloudflare account. We need two critical credentials:</p><ul><li><p>Cloudflare Account ID</p></li><li><p>Cloudflare API Token</p></li></ul><blockquote><p>Previously, you had to navigate to the Workers &amp; Pages dashboard and copy the Account ID from the bottom of the page. Now, it is displayed directly upon token creation, so we can copy it right from there.</p></blockquote><br><h3 id="api" tabindex="-1">Creating a Token with Worker Edit Permissions <a class="header-anchor" href="#api" aria-label="Permalink to &quot;Creating a Token with Worker Edit Permissions {#api}&quot;">​</a></h3><ol><li>Log in to your Cloudflare dashboard.</li></ol><p><a href="https://dash.cloudflare.com/login" target="_blank" rel="noreferrer">⚙️ Log in to Cloudflare</a></p><p><a href="https://dash.cloudflare.com/sign-up" target="_blank" rel="noreferrer">🪩 Create a Cloudflare Account</a></p><ol start="2"><li>Open the navigation menu on the left, type <strong>api</strong> in the <strong>Quick search</strong> field, and select <strong>Account API Tokens</strong> from the search suggestions.</li></ol><details class="details custom-block"><summary>View Screenshot</summary><p align="center"><img src="'+s+'" alt="Search for API tokens" width="1080px"></p><br><p align="center"><img src="'+l+'" alt="Select account API tokens" width="1080px"></p></details><br><ol start="3"><li>Click on the <strong>Create Token</strong> button.</li></ol><details class="details custom-block"><summary>View Screenshot</summary><p align="center"><img src="'+c+'" alt="Click on Create token" width="1080px"></p></details><br><ol start="4"><li>Under the template section, find <strong>Edit Cloudflare Workers</strong> (marked with a red arrow) and click <strong>Use template</strong>.</li></ol><details class="details custom-block"><summary>View Screenshot</summary><p align="center"><img src="'+d+'" alt="Change token template" width="1080px"></p><br><p align="center"><img src="'+p+'" alt="Select Edit Cloudflare Workers template" width="1080px"></p></details><br><ol start="5"><li>Under <strong>Token Expiration</strong>, choose a preferred expiration period based on your requirements, then proceed to the summary and creation step.</li></ol><details class="details custom-block"><summary>View Screenshot</summary><p align="center"><img src="'+T+'" alt="Token expiration time" width="1080px"></p><blockquote><p>Note: When your token expires, your deployed Worker will NOT stop working. However, you will no longer be able to deploy updates via GitHub Actions until you generate a new token and update your repository secrets.</p></blockquote></details><br><ol start="6"><li>Copy the generated API token. <strong>This token is displayed only once</strong>, so store it securely if you plan to use it elsewhere. Your <strong>Account ID</strong> is also displayed at the top of this page; make sure to copy it as well. Once both are saved, click <strong>Confirm</strong> to close the window.</li></ol><details class="details custom-block"><summary>View Screenshot</summary><p align="center"><img src="'+u+'" alt="Copy Cloudflare ID and Token" width="1080px"></p></details><br><h2 id="env" tabindex="-1">Step 3: Configuring GitHub Secrets <a class="header-anchor" href="#env" aria-label="Permalink to &quot;Step 3: Configuring GitHub Secrets {#env}&quot;">​</a></h2><p>Now, introduce the retrieved credentials to your forked repository so that GitHub Actions can authenticate with your Cloudflare account.</p><ol><li>In your forked repository, navigate to the <strong>Settings</strong> tab.</li></ol><details class="details custom-block"><summary>View Screenshot</summary><p align="center"><img src="'+h+'" alt="Go to repo settings" width="1080px"></p></details><br><ol start="2"><li>In the left sidebar, click on <strong>Secrets and variables</strong>, then select <strong>Actions</strong>.</li></ol><details class="details custom-block"><summary>View Screenshot</summary><p align="center"><img src="'+m+'" alt="Select Actions" width="1080px"></p></details><br><ol start="3"><li>Click <strong>New repository secret</strong> and define the secrets based on the table below:</li></ol><table tabindex="0"><thead><tr><th>Secret Name</th><th style="text-align:center;">Status</th><th>Default Value</th><th>Description</th></tr></thead><tbody><tr><td><code>CLOUDFLARE_API_TOKEN</code></td><td style="text-align:center;">✔️ Required</td><td>-</td><td>Your Cloudflare API Token with Worker edit permissions.</td></tr><tr><td><code>CLOUDFLARE_ACCOUNT_ID</code></td><td style="text-align:center;">✔️ Required</td><td>-</td><td>Your Cloudflare Account ID.</td></tr><tr><td><code>UUID</code></td><td style="text-align:center;">⚙️ Optional</td><td>Auto-generated during workflow execution if left blank</td><td>Your custom <a href="https://www.uuidgenerator.net" target="_blank" rel="noreferrer">UUID</a> (Version 4).</td></tr><tr><td><code>PROXYIP</code></td><td style="text-align:center;">⚙️ Optional</td><td><code>di.nscl.ir</code></td><td>Proxy IP used for routing traffic through Cloudflare-backed services.</td></tr></tbody></table><br><details class="details custom-block"><summary>View Screenshot</summary><p align="center"><img src="'+g+'" alt="Create secret 1" width="1080px"></p><br><p align="center"><img src="'+b+'" alt="Create secret 2" width="1080px"></p><br><p align="center"><img src="'+f+'" alt="Create final secret" width="1080px"></p></details><br><div class="danger custom-block"><p class="custom-block-title">Important Note</p><p>Both <code>CLOUDFLARE_ACCOUNT_ID</code> and <code>CLOUDFLARE_API_TOKEN</code> are mandatory; the Worker cannot be deployed without them. The other two parameters (<code>UUID</code> and <code>PROXYIP</code>) are optional. If omitted, a default Proxy IP is embedded into the code, and GitHub Actions will automatically generate a random <a href="https://www.uuidgenerator.net" target="_blank" rel="noreferrer">UUID</a> for your Worker. To find the generated UUID, check your Cloudflare dashboard, navigate to the deployed Worker, and inspect its environment variables under the Settings tab.</p><details class="details custom-block"><summary>View Screenshot</summary><p align="center"><img src="'+y+'" alt="View assigned UUID" width="1080px"></p><blockquote><p>To find alternative clean Proxy IPs, refer to this <a href="https://github.com/NiREvil/vless/blob/main/sub/ProxyIP.md" target="_blank" rel="noreferrer">Proxy Repository</a>.</p></blockquote></details></div><br><h2 id="manual-deploy" tabindex="-1">Step 4: Enabling and Running GitHub Actions <a class="header-anchor" href="#manual-deploy" aria-label="Permalink to &quot;Step 4: Enabling and Running GitHub Actions {#manual-deploy}&quot;">​</a></h2><p>By default, GitHub disables Actions on forked repositories. You must manually enable and trigger the workflow once.</p><ol><li><p>Go to the <strong>Actions</strong> tab at the top of your repository.</p></li><li><p>Click on the green button:</p></li></ol><p><strong>&quot;I understand my workflows, go ahead and enable them&quot;</strong></p><p>to authorize workflow runs.</p><details class="details custom-block"><summary>View Screenshot</summary><p align="center"><img src="'+k+'" alt="Enable Actions" width="1080px"></p></details><br><ol start="3"><li>From the left sidebar, click <strong>All workflows</strong>, then select the <strong>Deploy Worker</strong> workflow.</li></ol><details class="details custom-block"><summary>View Screenshot</summary><p align="center"><img src="'+w+'" alt="Select Deploy" width="1080px"></p></details><br><ol start="4"><li><p>On the right side of the screen, click the <strong>Run workflow</strong> dropdown button.</p></li><li><p>In the popup form, you can optionally override <code>Proxy IP</code>, <code>UUID</code>, and <code>Worker name</code> for this specific execution. (Leaving them empty will fall back to your repository secrets or default values).</p></li></ol><details class="details custom-block"><summary>View Screenshot</summary><p align="center"><img src="'+x+'" alt="Run workflow" width="1080px"></p></details><br><ol start="6"><li>Finally, click the green <strong>Run workflow</strong> button inside the popup.<br> After 30 to 60 seconds, a green checkmark will appear next to the run, indicating a successful deployment.</li></ol><details class="details custom-block"><summary>View Screenshot</summary><p align="center"><img src="'+_+'" alt="Deploy success" width="1080px"></p></details><br><div class="tip custom-block"><p class="custom-block-title">One-Time Execution Variables</p><p>Values entered directly into the <strong>Run workflow</strong> modal are disposable and will not be saved to your repository settings. This is useful for quickly testing different Proxy IPs or changing UUIDs on the fly.</p></div><br><blockquote><p><strong>Behind the Scenes</strong><br> When you click <strong>Run workflow</strong>, a GitHub Actions runner initializes, downloads, and configures the Rust <code>cargo</code> toolchain and <code>wasm-pack</code>, compiling the codebase into WebAssembly. Shortly after compilation, a new Worker named <code>0x00</code> is deployed to your Cloudflare account (or using the custom name provided in the workflow input).</p><p>If you wish to change the default Worker name permanently, edit the first line of <a href="https://github.com/NiREvil/zizifn/blob/c3a3367c543f3f0f88492597e7b8fea8f6b00fa3/wrangler.toml#L1" target="_blank" rel="noreferrer">wrangler.toml</a> in the repository.</p><details class="details custom-block"><summary>View Screenshot</summary><p align="center"><img src="'+v+'" alt="Worker name" width="1080px"></p></details></blockquote><br><h2 id="how-to-use" tabindex="-1">How to Use <a class="header-anchor" href="#how-to-use" aria-label="Permalink to &quot;How to Use&quot;">​</a></h2><h3 id="accessing-the-management-panel" tabindex="-1">Accessing the Management Panel <a class="header-anchor" href="#accessing-the-management-panel" aria-label="Permalink to &quot;Accessing the Management Panel&quot;">​</a></h3><p>After deployment, append your UUID to your Worker domain:</p><p><code>https://Your-workers.dev-URL/&lt;UUID&gt;</code></p><p><strong>For example:</strong></p><p><code>https://0x00.workers.dev/be0ff9df-1468-41a0-8865-796d1c6800db</code></p><blockquote><p>If you did not provide a UUID in the repository secrets or the manual workflow dispatch form, GitHub Actions generated a random <a href="https://www.uuidgenerator.net" target="_blank" rel="noreferrer">UUID</a> automatically. You can retrieve it by going to your Cloudflare dashboard &gt; Worker &gt; Settings tab under Secrets and Variables.</p></blockquote><br><h3 id="sub" tabindex="-1">Retrieving Subscription Links <a class="header-anchor" href="#sub" aria-label="Permalink to &quot;Retrieving Subscription Links {#sub}&quot;">​</a></h3><p>Your subscription link contains dozens of configurations pre-loaded with clean Cloudflare IPs. You can import them automatically using the buttons inside the panel.</p><p>Alternatively, if you need to copy the subscription link manually for other clients, press and hold (Long Touch) on any of the <code>Import to ...</code> buttons. Your browser will prompt for clipboard permission (only once). After allowing access, the specific subscription link for that client will be copied to your clipboard.</p>',89),e("details",{class:"details custom-block"},[e("summary",null,"View Screenshot"),e("p",{align:"center"},[e("img",{src:r,alt:"Copy Subscription link",width:"1080px"})]),e("h3",{subex:"",id:"subscription-link-examples",tabindex:"-1"},[I("Subscription Link Examples "),e("a",{class:"header-anchor",href:"#subscription-link-examples","aria-label":'Permalink to "Subscription Link Examples {subex}"'},"​")]),e("p",null,[e("strong",null,"For Xray Core clients:")]),e("p",null,[e("code",null,"https://0x00.workers.dev/xray/be0ff9df-1468-41a0-8865-796d1c6800db")]),e("p",null,[e("strong",null,"For Sing-box core clients:"),e("br"),e("code",null,"https://0x00.workers.dev/sb/be0ff9df-1468-41a0-8865-796d1c6800db")]),e("p",null,[e("strong",null,"For PattNG Client:"),e("br"),e("code",null,"https://0x00.workers.dev/xray-enhanced/be0ff9df-1468-41a0-8865-796d1c6800db")])],-1),o('<h2 id="pattng" tabindex="-1">Additional Details <a class="header-anchor" href="#pattng" aria-label="Permalink to &quot;Additional Details {#pattng}&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Differences Between xray, xray-enhanced, and sb</p><h4 id="the-xray-prefix" tabindex="-1">The <code>xray</code> prefix <a class="header-anchor" href="#the-xray-prefix" aria-label="Permalink to &quot;The `xray` prefix&quot;">​</a></h4><p>Optimized for clients powered by the Xray core, such as:<br> v2rayNG, MahsaNG, Hiddify, Nekoray, v2rayN, Streisand, Napsternet, NPVT, Happ, etc</p><br><h4 id="the-xray-enhanced-prefix" tabindex="-1">The <code>xray-enhanced</code> prefix <a class="header-anchor" href="#the-xray-enhanced-prefix" aria-label="Permalink to &quot;The `xray-enhanced` prefix&quot;">​</a></h4><p>Configurations that include Patterniha parameters by default—meaning they are configured with Final Mask, Cipher suites, and Undafe for fingerprinting.</p><p>Best suited for Xray-based clients that support these features, such as:<br> PattNG and v2rayNG</p><br><h4 id="the-sb-prefix" tabindex="-1">The <code>sb</code> prefix <a class="header-anchor" href="#the-sb-prefix" aria-label="Permalink to &quot;The `sb` prefix&quot;">​</a></h4><p>Optimized for clients powered by the Sing-box core, such as:<br> Nekobox, Exclave, Sing-box, Husi, Karing, etc.</p><br><h4 id="clean-cloudflare-ips" tabindex="-1">Clean Cloudflare IPs <a class="header-anchor" href="#clean-cloudflare-ips" aria-label="Permalink to &quot;Clean Cloudflare IPs&quot;">​</a></h4><p>The IP pool included in configurations is sourced from the <a href="https://github.com/NiREvil/vless/blob/main/Cloudflare-IPs.json" target="_blank" rel="noreferrer">NiREvil/vless</a> repository. The IP list is refreshed automatically every 4 hours.</p></div><br><div class="tip custom-block"><p class="custom-block-title"><strong>Optimized Configurations</strong></p><p>Recently, <a href="https://t.me/patt_channel_x/93" target="_blank" rel="noreferrer">Patterniha</a> proposed adding two parameters to configurations built on Cloudflare Workers to combat severe internet disruptions, constant connection drops in Iran, and poor upload speeds:</p><ul><li>Final Mask</li><li>Cipher suites</li></ul><p>To maximize performance, they released a fork of v2rayNG named PattNG on GitHub. Alongside normal configurations for v2rayNG, an <strong>Enhanced</strong> subscription is provided so that configurations are pre-tuned with these parameters. First, download and install <a href="https://github.com/patterniha/v2rayNG/releases" target="_blank" rel="noreferrer">PattNG</a> from Patterniha&#39;s GitHub releases, then open your panel, click <strong>Import to v2rayNG</strong>, and select <strong>Enhanced</strong>.<br><a href="https://github.com/patterniha/v2rayNG/releases" target="_blank" rel="noreferrer">PattNG GitHub Repository</a></p><br><p align="center"><img src="'+S+'" alt="PattNG" width="1920px"></p><br><div class="tip custom-block"><p class="custom-block-title">Resolving Google Service &amp; Gemini Issues</p><p>Our dear friend Mehdi has published a comprehensive guide addressing regional blocking and connection errors with Google AI Studio and Gemini.<br><a href="https://mehdi-hexing.github.io/mehdi-hexing/topics/WorkerPlacementGemini" target="_blank" rel="noreferrer">Click here to view the article.</a></p></div></div><blockquote><p><strong>● Deployment Engine</strong></p><ul><li>GitHub Actions runner (Ubuntu-24.04 VM)</li><li>Cloudflare Wrangler Action v4</li><li>Rust wasm-pack v0.13.1</li></ul><br><ul><li><strong>Many thanks to <a href="https://github.com/NiREvil" target="_blank" rel="noreferrer">NiREvil</a> and <a href="https://github.com/zizifn/edgetunnel" target="_blank" rel="noreferrer">zizifn</a></strong></li></ul><br></blockquote><div class="danger custom-block"><p class="custom-block-title">Security Warning</p><details class="details custom-block"><summary>Click to expand</summary><p><strong>Never provide sensitive Cloudflare tokens inside manual workflow input text fields!</strong></p><p>Values passed to manual run forms are stored in GitHub Actions workflow execution logs and become publicly visible if your repository is public. Sensitive Cloudflare credentials must always be stored via <strong>Step 3</strong> (Repository Secrets) so GitHub can encrypt them securely.</p></details></div>',6)])])}const z=C(G,[["render",q]]);export{H as __pageData,z as default};
